/**
 * Additional CPU, motherboard and exact RAM SKU catalog.
 * Physical specifications checked against official product pages/datasheets.
 * Prices, CPU score and AMD peakPower are simulator inputs, not shop offers
 * or measured performance. See docs/PLATFORM_SOURCES.md.
 */
function platform(product) {
  let specs;
  if (product.category === 'cpu') specs = [
    `${product.cores} ядер · ${product.threads} потоков`,
    `до ${product.boostClock.toLocaleString('ru-RU')} ГГц`,
    `${product.socket} · ${product.tdp} Вт`,
  ];
  if (product.category === 'motherboard') specs = [
    `${product.socket} · ${product.memoryType}`,
    `${product.formFactor} · ${product.memorySlots} слота RAM`,
    `${product.m2Slots} × M.2 NVMe`,
  ];
  if (product.category === 'ram') specs = [
    `${product.capacity} ГБ · ${product.modules} × ${product.capacity / product.modules} ГБ`,
    `${product.memoryType} · ${product.speed} MT/s · CL${product.cl}`,
    `${product.height} мм · ${product.sku}`,
  ];
  return { sourceCheckedAt: '2026-10-30', sourceVerification: 'manufacturer-product-specification', ...product, specs };
}

